import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, switch_cond])
    switch_cond.ir_type == "ConditionalStatement"
    switch_cond.type == 2 # SWITCH
    switch_cond.is_top == true

    # Traverse the chain of 'else_statement' to check for default coverage
    # We need to ensure that at least one branch in the chain is a default case
    # and that the chain is terminated correctly (no missing default at the end).
    has_default_in_chain := false
    current := switch_cond
    while {
        current != null
        current.ir_type == "ConditionalStatement"
        current.type == 2 # SWITCH or IF (in some IaC, else might be represented as IF)
    } {
        # Check if the current node is a default case
        # In the IR, default cases often have is_default = true or condition is Null
        if {
            current.is_default == true
        } {
            has_default_in_chain := true
        }
        if {
            current.condition.ir_type == "Null"
        } {
            has_default_in_chain := true
        }

        # Move to the next 'else_statement' in the chain
        current := current.else_statement
    }

    # If we traversed the entire chain and found no default, it's a vulnerability
    not has_default_in_chain

    result := {
        "type": "sec_no_default_switch",
        "element": switch_cond,
        "path": parent.path,
        "description": "Missing default branch in multi-branch conditional logic - Switch/If-Else chain lacks a fallback branch for unhandled values. (CWE-478)"
    }
}

