package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, cond])
    cond.ir_type == "ConditionalStatement"
    cond.is_top == true
    cond.type == 2

    count_default := count_default_branches(cond)
    count_default == 0

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default branch in switch statement - Switch statement lacks a default case for unhandled values. (CWE-478)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    walk(parent, [_, cond])
    cond.ir_type == "ConditionalStatement"
    cond.is_top == true
    cond.type == 1

    count_else := count_else_branches(cond)
    count_else == 0

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing else branch in if statement - If statement lacks an 'else' branch for unhandled states. (CWE-478)"
    }
}

count_default_branches(node) = total {
    total := sum({
        n |
        walk(node, [_, n])
        n.ir_type == "ConditionalStatement"
        n.is_default == true
    })
}

count_else_branches(node) = total {
    total := sum({
        1 |
        walk(node, [_, n])
        n.ir_type == "ConditionalStatement"
        n.else_statement != null
    })
}
